CREATE OR REPLACE FUNCTION public.vine_target(p_world uuid, c creature, p_x double precision, p_y double precision)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p, my_deed(p_world, c.keeper) dd
   where dd.world_id is not null and p.world_id = p_world and p.kind = 'furniture' and p.sub = vine_kind()
     and p.vine_at is null and coalesce(p.level, 0) = 0 and vine_soil(land_tile(p_world, p.x::int, p.y::int))
     and p.x between dd.x - work_range(c) and dd.x + work_range(c) and p.y between dd.y - work_range(c) and dd.y + work_range(c)
     and greatest(abs(p.x - dd.x), abs(p.y - dd.y)) <= work_range(c) and on_home_deed(p_world, c.keeper, p.x, p.y)
   order by (p.cx - p_x) ^ 2 + (p.cy - p_y) ^ 2, p.id limit 1
$function$
